# -*- coding: utf-8 -*-
"""시트 여러 장짜리 prose 엑셀 표본 — **시트 역할 관문의 재료** (B83).

사내 실물(설비 RFQ)의 모양을 창작으로 옮긴 것이다: 사양 몇 장만 지식이고
도면 목록은 참조, 가격·일정·표지는 읽을 것이 아니다. **사내 정보는 한 글자도
들어가지 않는다**(mock 자산의 규율 — 문서 7 §7.5).

    python tests/fixtures/make_rfq.py      → tests/fixtures/raw/RFQ01.xlsx (7시트)
"""
from pathlib import Path

from openpyxl import Workbook
from openpyxl.styles import Alignment

OUT = Path(__file__).resolve().parent / "raw" / "RFQ01.xlsx"

#: 시트 이름 → (줄 목록). 역할은 **사람이 정하는 것**이라 여기 적지 않는다.
SHEETS = {
    "표지": [["설비 견적 요청서"], ["문서번호 RFQ-2026-001"], ["작성 2026-09-22"],
            ["수신 협력사"]],
    "사양_기계": [
        ["1. 개요"],
        ["   본 문서는 노칭 설비의 기계 사양과 인수 조건을 정한다."],
        ["1.1 적용 범위"],
        ["   노칭 프레스와 그 부속 이송 장치, 금형 교환 설비에 적용한다."],
        ["1.2 용어"],
        ["   가압력은 프레스가 소재에 가하는 최대 힘을 말한다."],
        ["2. 기계 사양"],
        ["2.1 노칭 프레스"],
        ["   가압력은 120 kN 이상이어야 하며 편차는 3% 이내로 관리한다."],
        ["   금형 클리어런스는 0.02 mm 이하로 관리하고 매 로트마다 기록한다."],
        ["   금형 교환 시간은 10분 이내를 목표로 한다."],
        ["2.2 이송 장치"],
        ["   이송 정밀도는 ±0.05 mm 이내로 하고 온도 보정을 적용한다."],
        ["   이송 속도는 분당 30 미터 이상을 만족해야 한다."],
        ["2.3 금형"],
        ["   금형 재질은 분말 고속도강을 기본으로 하되 협의로 변경할 수 있다."],
        ["   금형 수명은 타발 50만 회 이상을 보증한다."],
        ["3. 인수 조건"],
        ["3.1 성능 시험"],
        ["   연속 8시간 운전에서 노칭 정밀도가 규격을 벗어나지 않아야 한다."],
        ["   버 높이는 규격 상한의 80% 이내를 유지해야 한다."],
        ["3.2 문서"],
        ["   설비 인수 시 조립도와 보전 지침서를 함께 제출한다."],
    ],
    "사양_전장": [
        ["1. 전장 사양"],
        ["   제어반은 이중화 전원을 갖추고 정전 시 안전 정지에 들어간다."],
        ["   제어 주기는 10 밀리초 이하로 유지한다."],
        ["2. 안전"],
        ["   비상정지는 이중 회로로 구성하고 매 시동 시 자가 진단을 수행한다."],
        ["   안전 펜스 개방 시 구동부 전원이 즉시 차단되어야 한다."],
        ["3. 통신"],
        ["   상위 시스템과는 산업용 이더넷으로 연결하고 이력을 남긴다."],
        ["   설비 알람은 코드와 발생 시각을 함께 전송한다."],
    ],
    "요구사항": [
        ["1. 공통 요구사항"],
        ["   설비는 스태킹 공정과 신호를 주고받으며 대기 시간을 최소화한다."],
        ["   적층 정렬도는 0.1 mm 이내를 보장해야 한다."],
        ["2. 유지보수"],
        ["   소모품 교체 주기는 운전 이력에서 자동으로 산출되어야 한다."],
        ["   원격 진단을 위한 접속 수단을 제공한다."],
        ["3. 납기"],
        ["   설치 완료 후 2주 이내에 성능 시험을 마친다."],
    ],
    "도면목록": [[f"DWG-{i:03d}"] for i in range(1, 31)],
    "가격": [["항목", "단가", "수량", "금액"]] + [[f"항목{i}", i * 10, i, i * 10 * i]
                                            for i in range(1, 13)],
    "일정": [["단계", "주차", "비고"], ["설계", 4, ""], ["제작", 12, ""],
            ["설치", 2, ""], ["검수", 2, ""], ["인수", 1, ""]],
}


def build():
    wb = Workbook()
    wb.remove(wb.active)
    for name, rows in SHEETS.items():
        ws = wb.create_sheet(title=name)
        for r, row in enumerate(rows, start=1):
            for c, v in enumerate(row, start=1):
                # 하위 항목은 **셀 들여쓰기**로 준다 — 실물 사양서의 모양이고,
                # 형태 판정의 indent 신호가 보는 것이 이것이다(문자열의 앞 공백이
                # 아니다). 문자열에만 공백을 두면 판정이 indent 0으로 읽는다.
                deep = isinstance(v, str) and v.startswith("   ")
                cell = ws.cell(row=r, column=c,
                               value=v.strip() if deep else v)
                if deep:
                    cell.alignment = Alignment(indent=1)
        ws.column_dimensions["A"].width = 60
    OUT.parent.mkdir(parents=True, exist_ok=True)
    wb.save(OUT)
    return OUT


if __name__ == "__main__":
    print(f"만들었다 — {build()} · 시트 {len(SHEETS)}장")
